3	/**
4	 * Membership tier for pet owners. An owner is {@code GOLD} when its household (owners sharing the
5	 * same {@code householdId}) has three or more members; otherwise it is {@code SILVER} when its
6	 * {@code namesakeCount} is 0 (no existing owner shares its first and last name) and it has an email
7	 * address, and {@code BRONZE} in every other case. Derived purely from the owner's own stored state
8	 * ({@code householdSize} and {@code namesakeCount} are recorded at create time), so it is
9	 * seed-independent. Used by the owner mapper to expose {@code membershipTier} on responses.
10	 */
11	public final class MembershipTier {
12	
13	    private MembershipTier() {
14	    }
15	
16	    /**
17	     * The membership tier for the given household size, namesake count and email: {@code GOLD} when
18	     * the household has three or more members; otherwise {@code SILVER} when the namesake count is
19	     * exactly 0 and the email is present (non-null, non-blank), and {@code BRONZE} otherwise.
20	     */
21	    public static String of(Integer householdSize, Integer namesakeCount, String email) {
22	        if (householdSize != null && householdSize >= 3) {
23	            return "GOLD";
24	        }
25	        boolean unique = namesakeCount != null && namesakeCount == 0;
26	        boolean hasEmail = email != null && !email.isBlank();
27	        return unique && hasEmail ? "SILVER" : "BRONZE";
28	    }
29	}
